/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getDescription = require( './description/get.js' );
var setDescription = require( './description/set.js' );

var getName = require( './name/get.js' );
var setName = require( './name/set.js' );

var getProperties = require( './properties/get.js' );

var getValue = require( './value/get.js' );
var setValue = require( './value/set.js' );


// VARIABLES //

var debug = logger( 'vega:signal:main' );


// MAIN //

/**
* Signal constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.name - unique name for the signal
* @param {string} [options.description] - text description of the signal
* @param {string} [options.value] - initial value of the signal
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide the `name` property
* @throws {Error} must provide valid options
* @returns {Signal} signal instance
*
* @example
* var signal = new Signal({
*     'name': 'indexDate'
* });
* // returns <Signal>
*/
function Signal( options ) {
	var nargs;
	var opts;
	var keys;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Signal ) ) {
		if ( nargs ) {
			return new Signal( options );
		}
		return new Signal();
	}
	EventEmitter.call( this );

	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	// Check for required properties...
	if ( !hasProp( options, 'name' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the signal name.' );
	}

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Signal, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Signal
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Signal, 'name', 'Signal' );

/**
* Text description of the signal.
*
* @name description
* @memberof Signal.prototype
* @type {(string|void)}
*
* @example
* var signal = new Signal({
*     'name': 'indexDate',
*     'description': 'A date value that updates in response to mousemove.'
* });
*
* var v = signal.description;
* // returns 'A date value that updates in response to mousemove.'
*/
setReadWriteAccessor( Signal.prototype, 'description', getDescription, setDescription );

/**
* Unique name for the signal.
*
* @name name
* @memberof Signal.prototype
* @type {string}
*
* @example
* var signal = new Signal({
*     'name': 'indexDate'
* });
*
* var v = signal.name;
* // returns 'indexDate'
*/
setReadWriteAccessor( Signal.prototype, 'name', getName, setName );

/**
* Signal properties.
*
* @name properties
* @memberof Signal.prototype
* @type {Array<string>}
*
* @example
* var signal = new Signal({
*     'name': 'indexDate'
* });
*
* var v = signal.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Signal.prototype, 'properties', getProperties );

/**
* Initial value of the signal.
*
* @name value
* @memberof Signal.prototype
* @type {Any}
*
* @example
* var signal = new Signal({
*     'name': 'indexDate',
*     'value': 'foo bar'
* });
*
* var v = signal.value;
* // returns 'foo bar'
*/
setReadWriteAccessor( Signal.prototype, 'value', getValue, setValue );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Signal.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var signal = new Signal({
*     'name': 'indexDate'
* });
*
* var v = signal.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Signal.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Signal;
